func (q *Queries) InvLockActivity(ctx context.Context, arg InvLockActivityParams) (InvLockActivityRow, error) {
	row := q.db.QueryRow(ctx, invLockActivity, arg.PromotionID, arg.SkuID)
	var i InvLockActivityRow
	err := row.Scan(&i.Quota, &i.Sold)
	return i, err
}

const invLockBizID = `-- name: InvLockBizID :exec
SELECT pg_advisory_xact_lock(hashtextextended($1::text, 0))
`

// 按 biz_id 串行化（事务级 advisory lock，提交或回滚即释放）。手工调整按「adj:员工:幂等键」锁；
// 阶段 1b 起下单扣减、SAGA 补偿、关单释放按订单号锁，退款回补按退款单号锁 —— 那几条路径都是
// 「先看这张单的流水、再决定写什么」，两步之间必须没有同一张单的另一次写插进来（见 inventory
// 包 saga.go 的文件头）。键空间不会撞：订单号、退款单号、「adj:」前缀互不相同。
//
// 相对调整的幂等落在库存服务这一侧（「同一个 biz_id 只生效一次」）：core 在结果未知时
// 会拿同一把 Idempotency-Key、也就是同一个 biz_id 再调一次。两次调用可能并发到达
// （第一次还在路上、第二次已经发出），「先查流水有没有这个 biz_id、没有再写」是两步，
// 不锁的话两次都会查到「没有」然后各加一遍。
//
// 不用唯一索引挡：biz_id 在下单那几类流水里本来就不唯一（一单多行），
// 给手工调整单开一条部分唯一索引要一条迁移，而这把锁只在手工调整这条低频路径上出现。
// 键是 biz_id 的 64 位哈希：不同租户、不同 biz_id 撞到同一个键只会让两次调整短暂排队。
func (q *Queries) InvLockBizID(ctx context.Context, bizID string) error {
	_, err := q.db.Exec(ctx, invLockBizID, bizID)
	return err
}

const invLockPromotionActivity = `-- name: InvLockPromotionActivity :many
SELECT a.sku_id, a.quota, a.sold
  FROM activity_stocks a
 WHERE a.promotion_id = $1
 ORDER BY a.sku_id
   FOR UPDATE
`

type InvLockPromotionActivityRow struct {
	SkuID int64
	Quota int32
	Sold  int32
}

// 整组设配额的第一步：锁住这个活动现有的全部配额行。「卖出过的 SKU 不能移出活动 /
// 配额不能低于已售」在这把锁之下判，判与写同一个快照 —— 与之竞争的是下单扣减
// （InvLockActivity 锁同一批行），扣减要么排在判定之前（判定看到新的已售），要么之后。
func (q *Queries) InvLockPromotionActivity(ctx context.Context, promotionID int64) ([]InvLockPromotionActivityRow, error) {
	rows, err := q.db.Query(ctx, invLockPromotionActivity, promotionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []InvLockPromotionActivityRow
	for rows.Next() {
		var i InvLockPromotionActivityRow
		if err := rows.Scan(&i.SkuID, &i.Quota, &i.Sold); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const invLockStoreStock = `-- name: InvLockStoreStock :many

SELECT inv.sku_id, inv.available_qty, inv.warning_qty
  FROM inventories inv
 WHERE inv.store_id = $1
   AND inv.sku_id = ANY($2::bigint[])
 ORDER BY inv.sku_id
   FOR UPDATE
`

type InvLockStoreStockParams struct {
	StoreID int64
	SkuIds  []int64
}

type InvLockStoreStockRow struct {
	SkuID        int64
	AvailableQty int32
	WarningQty   int32
}

// ---------------------------------------------------------------------------
// 阶段 1b：下单扣减 / 补偿 / 关单释放 / 退款回补（全部按单号幂等，见 inventory 包 saga.go）
// ---------------------------------------------------------------------------
// 下单扣减的第一步：按 sku_id 升序锁住这家店这批 SKU 的库存行，并读出水位。
//
// 先锁、再判、最后写，而不是逐行「条件 UPDATE、0 行即缺货」：一单多行时，第三行缺货的话前两行
// 已经扣了，要么靠保存点回滚，要么让整个事务失败 —— 而扣减被拒要**提交**一行拒绝流水
// （saga.go 的「扣减被拒为什么是成功」）。锁住之后判定与写入之间没有别人能改这几行，
// 判过了就一定扣得成。缺行不回（缺行 ≡ 可售 0，调用方判成不足）。
//
// 按 sku_id 升序拿锁：与补偿、关单释放、退款回补同一个全局顺序，两张共享 SKU 的单
// 一个扣一个补不会互相等成死锁。库存行一律先于活动配额行加锁（InvLockActivity 在其后）。
func (q *Queries) InvLockStoreStock(ctx context.Context, arg InvLockStoreStockParams) ([]InvLockStoreStockRow, error) {
	rows, err := q.db.Query(ctx, invLockStoreStock, arg.StoreID, arg.SkuIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []InvLockStoreStockRow
	for rows.Next() {
		var i InvLockStoreStockRow
		if err := rows.Scan(&i.SkuID, &i.AvailableQty, &i.WarningQty); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const invLowStock = `-- name: InvLowStock :many
SELECT i.store_id, i.sku_id, i.available_qty, i.warning_qty
  FROM inventories i
 WHERE i.available_qty <= i.warning_qty
   AND i.store_id = ANY($1::bigint[])
   AND NOT (i.sku_id = ANY($2::bigint[]))
 ORDER BY i.available_qty - i.warning_qty, i.available_qty, i.store_id, i.sku_id
 LIMIT $3
`

type InvLowStockParams struct {
	StoreIds      []int64
	ExcludeSkuIds []int64
	RowLimit      int32
}

type InvLowStockRow struct {
	StoreID      int64
	SkuID        int64
	AvailableQty int32
	WarningQty   int32
}

// 库存预警（报表）。i.available_qty <= i.warning_qty 必须与 idx_inventories_warning
// 的谓词逐字一致，规划器才认得出那条部分索引。
//
// 门店范围由 core 给成**显式的 id 列表**（未软删、落在筛选与员工范围内的门店），
// 软删 SKU / 软删商品下的 SKU 由 core 给成排除列表 —— 拆分前那三个 JOIN 做的判断
// 就是这两件，库存库里没有那几张表，只能由 core 判完把结果递过来。
// 排除列表通常很短（软删是少数），门店列表是门店数量级。
func (q *Queries) InvLowStock(ctx context.Context, arg InvLowStockParams) ([]InvLowStockRow, error) {
	rows, err := q.db.Query(ctx, invLowStock, arg.StoreIds, arg.ExcludeSkuIds, arg.RowLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []InvLowStockRow
	for rows.Next() {
		var i InvLowStockRow
		if err := rows.Scan(
			&i.StoreID,
			&i.SkuID,
			&i.AvailableQty,
			&i.WarningQty,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const invPurgeLogsBefore = `-- name: InvPurgeLogsBefore :execrows
DELETE FROM inventory_logs
 WHERE ctid = ANY(ARRAY(SELECT l.ctid FROM inventory_logs l
                         WHERE l.created_at < $1::timestamptz
                         LIMIT $2::int))
`

type InvPurgeLogsBeforeParams struct {
	Before pgtype.Timestamptz
	Batch  int32
}

// 库存流水按保留期分批清理（service/retention.go，默认留 180 天），删法同 db/queries/retention.sql
// 的文件头：带 LIMIT 的 ctid 子查询，走 idx_inv_logs_created (merchant_id, created_at)（00173）。
//
// 删老流水对别处判断的影响，逐个看过（InvBizTrail 的三个用途 + 另外两处）：
//
//	· 关单释放 / SAGA 补偿按流水**净值**算还欠多少（inventory/saga.go 的 putBack）：流水删了
//	  净值是 0，什么都不补 —— 不会重复加库存；
//	· 退款回补（inventory/local_orders.go 的 RestockForRefund）按「有没有这张退款单的回补流水」
//	  判重放：**这是唯一一处删了会出错的**。同一张退款单的回补在它的流水被删之后再来一次，
//	  会再加一遍库存。它只来自 outbox 的重试，正常在分钟级完成；死信是永久保留、要人处理的，
//	  保留期（默认 180 天）必须长于「死信最晚会被人重新投递」的时间 —— 别配到 30 天以下；
//	· 手工调整判重（InvLockBizID / InvFindManualLog）只在同一次操作的重试窗口里有意义；
//	· InvStockoutDays 取某天收盘水位：收盘前的流水删了，会落到「收盘后第一条流水的
//	  before_available」或「现在的可售」，两者都等于那天收盘的水位（中间没有别的变动）。
func (q *Queries) InvPurgeLogsBefore(ctx context.Context, arg InvPurgeLogsBeforeParams) (int64, error) {
	result, err := q.db.Exec(ctx, invPurgeLogsBefore, arg.Before, arg.Batch)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

